import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

public class QueryStringUtilTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	public void directedLanguageLiteralIncludesBaseDirection() {
		Literal literal = VF.createLiteral("שלום", "he", Literal.BaseDirection.RTL);

		assertEquals("'''שלום'''@he--rtl", QueryStringUtil.appendValue(new StringBuilder(), literal).toString());
	}

	@Test
	public void literalBackslashIsEscaped() {
		Literal literal = VF.createLiteral("a\\");

		assertEquals("'''a\\\\'''^^<http://www.w3.org/2001/XMLSchema#string>",
				QueryStringUtil.appendValue(new StringBuilder(), literal).toString());
	}

	@Test
	public void iriThatBreaksOutOfIriRefIsRejected() {
		IRI iri = VF.createIRI("urn:a> ?p ?o } UNION { ?s ?p ?o } #");

		assertThrows(IllegalArgumentException.class, () -> QueryStringUtil.appendValue(new StringBuilder(), iri));
	}

	@Test
	public void languageTagThatBreaksOutOfLangTagIsRejected() {
		Literal literal = VF.createLiteral("x", "en } UNION { ?s ?p ?o } #");

		assertThrows(IllegalArgumentException.class, () -> QueryStringUtil.appendValue(new StringBuilder(), literal));
	}
}
